(function () {
  "use strict";
  const obj = {
    name: "obj",
    regular() { return this?.name; },
    arrow: () => typeof this,
    nested() {
      function inner() { return this?.name; }
      const innerArrow = () => this.name;
      return [inner(), innerArrow()];
    },
    deep: { name: "deep", who() { return this.name; } },
  };

  console.log(obj.regular());          // obj
  const detached = obj.regular;
  console.log(detached());             // undefined
  console.log(obj.nested());           // [undefined, "obj"]
  console.log(obj.deep.who());         // deep
  console.log((0, obj.regular)());     // undefined
  console.log(detached.call({ name: "call" }));            // call
  console.log(detached.bind({ name: "bound" }).call({ name: "x" })); // bound
  setTimeout(obj.regular, 0);          // lost this (undefined inside)
})();

