Array.prototype.myMap = function (cb, thisArg) {
  if (typeof cb !== "function") throw new TypeError(cb + " is not a function");
  const result = [];
  for (let i = 0; i < this.length; i++) {
    if (i in this) result[i] = cb.call(thisArg, this[i], i, this);
  }
  return result;
};
console.log([1, 2, 3].myMap((n, i) => n * 2 + i));

Function.prototype.myBind = function (context, ...preset) {
  const fn = this;
  return function (...later) {
    return fn.apply(context, [...preset, ...later]);
  };
};
function intro(g, p) { return `${g}, ${this.name}${p}`; }
console.log(intro.myBind({ name: "Asha" }, "Hello")("!"));

const flatten = (arr, depth = Infinity) =>
  arr.reduce((acc, v) => (Array.isArray(v) && depth > 0 ? acc.concat(flatten(v, depth - 1)) : acc.concat(v)), []);
console.log(flatten([1, [2, [3, [4]]]], 2));

const deepEqual = (a, b) => {
  if (a === b) return true;
  if (typeof a !== "object" || typeof b !== "object" || !a || !b) return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  return ka.length === kb.length && ka.every((k) => deepEqual(a[k], b[k]));
};
console.log(deepEqual({ a: [1, { b: 2 }] }, { a: [1, { b: 2 }] }), deepEqual({ a: 1 }, { a: 2 }));

const fizzBuzz = (n) => Array.from({ length: n }, (_, i) => ((i + 1) % 15 === 0 ? "FizzBuzz" : (i + 1) % 3 === 0 ? "Fizz" : (i + 1) % 5 === 0 ? "Buzz" : i + 1));
console.log(fizzBuzz(15).join(" "));

function myPromiseAll(promises) {
  return new Promise((resolve, reject) => {
    const results = [];
    let completed = 0;
    if (promises.length === 0) return resolve(results);
    promises.forEach((p, index) => {
      Promise.resolve(p).then((value) => {
        results[index] = value;                  // keep the original order
        if (++completed === promises.length) resolve(results);
      }, reject);
    });
  });
}
const wait = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));
myPromiseAll([wait(30, "slow"), 42, wait(10, "fast")]).then(console.log);
myPromiseAll([wait(10, "ok"), Promise.reject(new Error("boom"))]).catch((e) => console.log("rejected:", e.message));
